#!/usr/bin/env bash
# Acceptance checks for f0208. SEQUESTERED: never edit during execution.
# One `check "ACn: ..."` per Checked acceptance criterion, in the same order as the issue doc.
HERE="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd -P)" # physical: tests/run strips the physical cwd
source "$(git -C "$HERE" rev-parse --show-toplevel)/z-nile/lib/ac.sh" # cds to the item's project home
# sequestered specs: here before `./zn done`, promoted to its project's tests/acceptance/f0208 after it
A="$HERE/acceptance"
[[ -d $A ]] || A="$PWD/tests/acceptance/f0208"

# Work outside `check` is limited to running a spec through `tests/run` (which AC_LIST=1 list mode refuses),
# `./zn members` and other cheap reads; everything else goes inside `check`.
check "AC1: the play decision and the card's buttons: a free start due or a held play goes, in every mode; a failed read goes on the portal's pass, in every mode; a busy read reads again; with nothing held closed mode cannot sell, else the player buys; intents and statuses checked field by field; one button per mode (PLAY, ARENA on Snake, 2 PLAYERS on Invaders and Asteroids) with FREE or 5 R\$ struck through and 1 R\$; the player's own play as a note on its card above name-only buttons, CANCEL and INVITE FRIEND while waiting; every text at least 12 px on every screen; the keys between the default controls and the test purchase screen and clear of the carousel's" lune run tests/run -- "$A/play.spec.luau"
check "AC2: the waiting lines and the arenas: a player waits in one line at most, the second player on a title's line is paired with the first and both leave it, lines per title; an ARENA player joins the arena on record while fewer than 24 were sent and it opened under 600 s ago, else opens a new one; nothing mutates its input" lune run tests/run -- "$A/pairing.spec.luau"
check "AC3: the server adapter on a stub server: Receipts installed once; the record read through the Wallet and PaidPlay's status at os.time(); a free start or a held play teleports at once to the title's place from the attributes; a failed read writes the pass then teleports; busy reads again for up to 10 s; nothing held opens the play product and teleports only on its grant (a close not bought, or a receipt later than 30 s, ends it); closed mode sells nothing; ARENA to the shared arena's reserved server, 2 PLAYERS paired in one teleport to a fresh reserved server; one play at a time, Travel's cool-down, nothing for a player who left, nothing in TeleportData" lune run tests/run -- "$A/server.spec.luau"
check "AC4: invites on a stub server: the invite recorded by the inviter's id (this server's job and the title, 600 s); an invited friend who lands in another portal server is sent to the inviter's when the invite is on record and they are friends, and nowhere otherwise" lune run tests/run -- "$A/invites.spec.luau"
check "AC5: the client adapter on a stub client: each card's buttons from the server's states with their prices as rich text, placed by Play's slots and note box, never gamepad-selectable; taps, the carousel's PLAY, 2 or X, Backspace or B, I or Y ask the server on the press, nothing while the test purchase screen is open; the player's play and other players' waits drawn on their cards; the invite prompt with the player's id as launch data; one ask of the cards' states after it listens; start returns at once" lune run tests/run -- "$A/client.spec.luau"
check "AC6: in the built portal place: ReplicatedStorage.Remotes.Play; Play requiring only Card, Pairing and Arena leaves, Modes requiring only Play; Plays and Invites in ServerScriptService.Server, Plays reaching the Wallet and Receipts and booted by the server's Main; PlayButtons and the test purchase screen booted by the client's Main; nothing a client reads requiring a server module; the architecture map declaring the play buttons with Play -> Card" lune run tests/run -- "$A/place.spec.luau"
check "AC7: Play, Pairing and Arena have unit specs; Logic stays engine-free, every dependency is declared, and every feature has unit specs" bash -c 'test -d tests/unit/Play && test -d tests/unit/Pairing && test -d tests/unit/Arena && lune run tests/run -- tests/meta/architecture.spec.luau'

finish
